mapper.select:
/** pcfSql - selectBoard - 게시물 목록 조회 */ SELECT A.NSEQNO as "nSeqNo" /* 01_게시판 일련번호 */ , A.VEMPLNO as "vEmplNo" /* 02_작성자 사번 */ , A.VNAME as "vName" /* 03_작성자 성명 */ , A.VSUBJECT as "vSubject" /* 04_제목 */ , A.VCONTENT as "vContent" /* 05_내용 */ , A.NHIT as "nHit" /* 07_조회수 */ , A.VYYYYMMDD as "vYyyymmdd" /* 08_작성일자 */ , A.VHHMMSS as "vHhmmss" /* 09_작성일시 */ , A.NREF as "nRef" /* 10_ */ , A.NSTEP as "nStep" /* 11_ */ , A.NLEV as "nLev" /* 12_ */ , A.NPSEQNO as "nPseqNo" /* 13_ */ , A.NREPLY as "nReply" /* 14_ */ , B.nFileSeqNo as "nFileSeqNo" /* 15_파일 일련번호 */ FROM TCA4010 A, ( SELECT NSEQNO , MIN(NFILESEQNO) as nFileSeqNo FROM TCA4011 GROUP BY NSEQNO ) B
A.NSEQNO = B.NSEQNO(+)
ORDER BY A.NSEQNO DESC

/** pcfSql - selectPassword - 비밀번호 조회 */
SELECT
   VPASSWORD   as nPassword
FROM
   TCA4010

   NSEQNO = #{nSeqNo}

/** pcfSql - selectBoardFile - 첨부파일 조회 */ SELECT NSEQNO as "nSeqNo" , NFILESEQNO as "nFileSeqNo" , VFILENAME as "vFileName" , VTEMPFILENAME as "vTempFileName" , VFILEPATH as "vFilePath" , VFILEEXTENSION as "vFileExtension" , VPDFFILENAME as "vPdfFileName" , VPDFCREATEDATE as "vPdfCreateDate" FROM TCA4011
NSEQNO = #{nSeqNo}
AND NFILESEQNO = #{nFileSeqNo}

mapper.insert:
      /** pcfSql - insertBoard - 새로운 게시물을 입력 */
      
      
         SELECT NVL(MAX(NSEQNO) + 1, 1) FROM TCA4010
      

      
      

      INSERT INTO TCA4010 (
           NSEQNO
         , VEMPLNO
         , VNAME
         , VSUBJECT
         , VCONTENT
         , NHIT
         , VYYYYMMDD
         , VHHMMSS
         , NREF
         , NSTEP
         , NLEV
         , NPSEQNO
         , NREPLY
      ) VALUES
      (
           #{nSeqNo,   jdbcType=INTEGER}
         , #{vEmplNo,  jdbcType=VARCHAR}
         , #{vName,    jdbcType=VARCHAR}
         , #{vSubject, jdbcType=VARCHAR}
         , #{vContent, jdbcType=VARCHAR}
         , #{nHit,     jdbcType=INTEGER}
         , TO_CHAR(SYSDATE,'YYYY-MM-DD')
         , TO_CHAR(SYSDATE, 'HH24:MI:SS')
         , #{nRef,     jdbcType=INTEGER}
         , #{nStep,    jdbcType=INTEGER}
         , #{nLev,     jdbcType=INTEGER}
         , #{nPseqNo,  jdbcType=INTEGER}
         , #{nReply,   jdbcType=INTEGER}
      )

      /** pcfSql - insertBoardFile - 게시판 첨부파일 저장 */
      
      
         SELECT NVL(MAX(NFILESEQNO) + 1, 1) FROM TCA4011 WHERE NSEQNO = #{nSeqNo}
      

      /** pcfSql - insertBoardFile - 게시판 입력, 답변 */
      INSERT INTO TCA4011 (
           NSEQNO
         , NFILESEQNO
         , VFILENAME
         , VTEMPFILENAME
         , VFILEPATH
         , VFILEEXTENSION
      ) VALUES
      (
           #{nSeqNo,         jdbcType=INTEGER}
         , #{nFileSeqNo,     jdbcType=INTEGER}
         , #{vFileName,      jdbcType=VARCHAR}
         , #{vTempFileName,  jdbcType=VARCHAR}
         , #{vFilePath,      jdbcType=VARCHAR}
         , #{vFileExtension, jdbcType=VARCHAR}
      )

mapper.update:
/** pcfSql - updateBoard - 게시물 내용을 수정 */ UPDATE TCA4010
VNAME = #{vName} , VSUBJECT = #{vSubject} , VCONTENT = #{vContent} , VPASSWORD = #{vPassword},
NSEQNO = #{nSeqNo}

mapper.delete:
/** pcfSql - deleteBoard - 게시물을 삭제 */
DELETE FROM TCA4010

   NSEQNO = #{nSeqNo}

/** pcfSql - deleteBoardFile - 게시물 첨부파일을 삭제 */
DELETE FROM TCA4011

       NSEQNO = #{nSeqNo}
   AND NFILESEQNO = #{nFileSeqNo}

/** pcfSql - updateBoardFile - 게시물 첨부파일을 수정 */
UPDATE TCA4011

    VPDFFILENAME   = #{vPdfFileName}   , 
    VPDFCREATEDATE = TO_CHAR(SYSDATE, 'YYYY-MM-DD HH24:MI:SS') , 


   NSEQNO = #{nSeqNo}
   AND NFILESEQNO = #{nFileSeqNo}

mapper.update:
/** pcfSql - updateHitCount - 게시물 조회수를 증가 */
UPDATE
   TCA4010

   NHIT = NHIT + 1


   NSEQNO = #{nSeqNo}
